640				<article class="card">
641					<h3>Interactive Counter</h3>
642					<p>This counter demonstrates state management and ARIA live regions for accessible dynamic content.</p>
643					<div class="counter">
644						<button id="decrease" type="button" aria-label="Decrease count by 1">−</button>
645						<output id="count" aria-live="off">0</output>
646						<button id="increase" type="button" aria-label="Increase count by 1">+</button>
