715			const themeToggle = document.getElementById('theme-toggle');
716			const htmlElement = document.documentElement;
717			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
718	
719			const themeColors = { light: '#ffffff', dark: '#121212' };
720			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
721			themeColorMetas.forEach((meta) => {
722				meta.dataset.defaultContent = meta.content;
723			});
724	
725			const updateThemeUI = () => {
726				const forced = htmlElement.dataset.theme;
727				const isDark = forced ? forced === 'dark' : prefersDark.matches;
728				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
729				themeToggle.textContent = isDark ? '☀️' : '🌙';
730				themeToggle.setAttribute('aria-label', label);
731				themeToggle.title = label;
732				themeColorMetas.forEach((meta) => {
733					meta.content = forced ? themeColors[forced] : meta.dataset.defaultContent;
734				});
735			};
736	
737			if (themeToggle) {
738				themeToggle.hidden = false;
739				updateThemeUI();
740	
741				themeToggle.addEventListener('click', () => {
742					const systemTheme = prefersDark.matches ? 'dark' : 'light';
743					const current = htmlElement.dataset.theme || systemTheme;
744					const next = current === 'dark' ? 'light' : 'dark';
745					// Choosing the system theme clears the override so the page follows the OS again.
746					try {
747						if (next === systemTheme) {
748							delete htmlElement.dataset.theme;
749							localStorage.removeItem('theme');
750						} else {
751							htmlElement.dataset.theme = next;
752							localStorage.setItem('theme', next);
753						}
754					} catch {}
755					updateThemeUI();
756				});
757	
758				prefersDark.addEventListener('change', () => {
759					if (!htmlElement.dataset.theme) {
760						updateThemeUI();
761					}
762				});
763			}
764	
765			const copyrightYear = document.getElementById('copyright-year');
766			if (copyrightYear) {
767				copyrightYear.textContent = String(new Date().getFullYear());
768			}
769	
770			const messages = [
771				"This update was announced to screen readers!",
772				"Dynamic content updates work with aria-live regions.",
773				"Live regions are essential for accessible web apps.",
774				"Try this with a screen reader like NVDA or JAWS!"
775			];
776			let nextMessage = 0;
777			let count = 0;
778			const announceBtn = document.getElementById('announce');
779			const liveMessage = document.getElementById('live-message');
780			const contactForm = document.getElementById('contact-form');
781			const emailInput = document.getElementById('email');
782			const messageInput = document.getElementById('message');
783			const messageCount = document.getElementById('message-count');
784			const formStatus = document.getElementById('form-status');
785			const countDisplay = document.getElementById('count');
786			const countMessage = document.getElementById('count-message');
787			const decreaseBtn = document.getElementById('decrease');
788			const increaseBtn = document.getElementById('increase');
789			const resetBtn = document.getElementById('reset');
790	
791			const updateCountDisplay = () => {
792				countDisplay.textContent = String(count);
793				countMessage.textContent = `Count is ${count}.`;
794			};
795	
796			if (countDisplay && countMessage) {
797				decreaseBtn?.addEventListener('click', () => {
798					count--;
799					updateCountDisplay();
800				});
801	
802				increaseBtn?.addEventListener('click', () => {
803					count++;
804					updateCountDisplay();
805				});
806	
807				resetBtn?.addEventListener('click', () => {
808					count = 0;
809					updateCountDisplay();
810				});
811			}
812	
813			if (announceBtn && liveMessage) {
814				announceBtn.addEventListener('click', () => {
815					liveMessage.textContent = messages[nextMessage];
816					nextMessage = (nextMessage + 1) % messages.length;
817				});
818			}
819	
820			if (contactForm) {
821				const emailError = document.getElementById('email-error');
822				const submitBtn = contactForm.querySelector('button[type="submit"]');
823				const isSending = () => submitBtn.getAttribute('aria-disabled') === 'true';
824	
825				// Set here rather than in the markup so native validation still works without JavaScript.
826				contactForm.noValidate = true;
827	
828				const setFormStatus = (message, state) => {
829					formStatus.textContent = message;
830					if (state) {
831						formStatus.dataset.state = state;
832					} else {
833						delete formStatus.dataset.state;
834					}
835				};
836	
837				const updateMessageCount = () => {
838					if (messageInput && messageCount) {
