856						emailInput.removeAttribute('aria-invalid');
857						emailInput.setAttribute('aria-describedby', 'email-help');
858					}
859				};
860	
861				const validateEmail = () => {
862					let message = '';
863					if (emailInput.validity.valueMissing) {
864						message = 'Enter your email address.';
865					} else if (!emailInput.validity.valid) {
866						message = 'Enter an email address in the format name@example.com.';
867					}
868					setEmailError(message);
869					return !message;
870				};
871	
872				emailInput.addEventListener('blur', () => {
873					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
874						validateEmail();
875					}
876				});
877	
878				emailInput.addEventListener('input', () => {
879					if (emailInput.hasAttribute('aria-invalid')) {
880						validateEmail();
881					}
882				});
883	
884				contactForm.addEventListener('input', () => {
885					if (!isSending()) {
886						setFormStatus('');
887					}
888				});
889	
890				contactForm.addEventListener('submit', async (event) => {
891					event.preventDefault();
892					if (isSending()) {
893						return;
894					}
895					setFormStatus('');
896					if (!validateEmail()) {
897						emailInput.focus();
898						return;
899					}
900					const originalText = submitBtn.textContent;
901					// aria-disabled keeps keyboard focus on the button, unlike the disabled attribute.
902					submitBtn.setAttribute('aria-disabled', 'true');
903					submitBtn.setAttribute('aria-busy', 'true');
