911					messageInput.readOnly = false;
912					contactForm.reset();
913					setEmailError('');
914					updateMessageCount();
915					submitBtn.removeAttribute('aria-disabled');
916					submitBtn.removeAttribute('aria-busy');
917					submitBtn.textContent = originalText;
918					setFormStatus("Thanks! This is a demo, so nothing was sent.");
919					emailInput.focus();
920				});
921			}
922		</script>
